		public static string NodeForFeedType(FeedType feedType)
		{
			switch (feedType)
			{
			case FeedType.NewsFeed:
				return "section_feed.environment(iphone)";
			case FeedType.Timeline:
				return "timeline_units";
			case FeedType.Group:
				return "group_stories";
			case FeedType.PinnedGroup:
				return "group_pinned_stories";
			case FeedType.Event:
				return "event_stories";
			default:
				throw new Exception("Unknown feed type");
			}
		}

